(1, 4, '2025-04-14T06:24:00Z', '2025-04-14T06:24:00Z', 'out', 'instruction', 'Radio 4: you are detached from Group 2. Border Patrol helicopter is inbound. Find a landing zone, mark it, and stand fast there.'),
(2, 4, '2025-04-14T07:33:23Z', '2025-04-14T07:33:28Z', 'in', 'evidence', 'Landing zone marked: open grass bench, about 150 by 100 m, nearly level, no overhead obstructions. Standing fast with lights.'),
(3, 3, '2025-04-14T08:25:17Z', '2025-04-14T08:25:17Z', 'out', 'instruction', 'Radio 3: you are now with Group 3. Join them in S4 and take the east side.'),
(4, 1, '2025-04-14T08:37:31Z', '2025-04-14T08:37:34Z', 'in', 'evidence', 'Boot prints in the wash, single set, heading east. Flagged.'),
